startEvent=function(){let e=nextEvent();if(S.active||e.day>S.day)return;let key=formatKey6(e),f=FORMAT6[key];if(f.n===24)addField6();let all=S.teams.filter(t=>t.id!==S.club&&(!t.fiction||f.n===24)).map(t=>t.id).sort((a,b)=>strength(S.teams[b])-strength(S.teams[a]));let entrants=[S.club,...all.slice(0,f.n-1)].sort((a,b)=>strength(S.teams[b])-strength(S.teams[a]));let a=S.active={event:e.id,format6:true,formatKey6:key,phase:'circuit',stage:'Жеребьёвка',schedule:[],cursor:0,entrants,seeds:Object.fromEntries(entrants.map(id=>[id,strength(S.teams[id])])),swissRound:0,stage6:'groups',placements:{},score:[0,0],maps:[],live:null,seriesDone:false,round:0,totalRounds:1,pairs:[],bracket:[],bo:3};e.entrants=entrants;e.formatKey6=key;e.format='circuit-v6';if(f.kind==='de'){de8_6(a,entrants);a.stage6='playoffs'}else if(f.kind==='swiss')swissRound6(a);else if(f.kind==='gsl')gsl6(a);else roundRobin6(a,entrants,f.size,f.bo);selectedBracket=e.id;log('Начался '+e.name+': '+f.label);seekMatch6();};
function aiSeries6(pair,bo=3){let score=[0,0],maps=[];while(bo===2?maps.length<2:score.every(x=>x<Math.floor(bo/2)+1)){let m=makeLive4({opponent:pair[1]},autoDraft(pair),pair),steps=0;while(m.finishedSide==null&&steps++<7200)simulateTick4(m,10);if(m.finishedSide==null)throw Error('Матч не завершился за 20 игровых часов; случайный победитель не назначен.');score[m.finishedSide]++;maps.push({winner:pair[m.finishedSide],duration:m.clock,gold:m.gold});fatigueMap6(pair,m.clock);}return {score:score.join(':'),w:score[0]===score[1]?null:pair[score[0]>score[1]?0:1],l:score[0]===score[1]?null:pair[score[0]>score[1]?1:0],maps};}
function recordNode6(a,n,sc){n.score=sc;let pair=n.pair.map(v=>resolve6(a,v)),s=sc.split(':').map(Number);n.w=s[0]===s[1]?null:pair[s[0]>s[1]?0:1];n.l=s[0]===s[1]?null:pair[s[0]>s[1]?1:0];if(n.outPlace)a.placements[n.l]=n.outPlace;if(n.championship)a.placements[n.w]=1;}
