function finishEvent6(a){let e=S.events.find(e=>e.id===a.event),last=a.schedule.at(-1),champion=last.w,place=a.entrants.includes(S.club)?a.placements[S.club]||9:null;for(let id of a.entrants)if(!a.placements[id])a.placements[id]=9;e.done=true;e.place=place;e.champion=champion;e.schedule6=structuredClone(a.schedule);e.placements6=a.placements;e.seeds6=a.seeds;e.groupIds6=a.groupIds;e.gsl6=a.gsl;e.pairingFallback=a.pairingFallback||false;let shares={1:.36,2:.19,3:.11,4:.075,5:.04,7:.025,9:.006,13:.004,14:.003};e.reward=place===null?0:Math.round(e.pool*(shares[place]||.003));money(e.reward,e.name+' · место '+place);S.prizes+=e.reward;if(place===1)S.trophies++;S.teams[champion].points+=100;my().points+=place===null||place===1?0:Math.max(5,70-place*7);log(e.name+' завершён. Место '+place+', призовые '+cash(e.reward)+'. Чемпион '+S.teams[champion].name+'.');S.active=null;selectedBracket=e.id;ensureTournamentCalendar();go('bracket');toast('Турнир завершён. Призовые зачислены.')}
