roundTitle=function(i,total){return S.active?.format6?S.active.stage:roundLegacy6(i,total)};
function circuitTable6(a,ids){return `<div class="table-wrap"><table><thead><tr><th>КОМАНДА</th><th>В–Н–П</th><th>КАРТЫ</th><th>БУХГОЛЬЦ</th></tr></thead><tbody>${ranks6(a,ids).map(r=>`<tr class="${r.id===S.club?'own-row':''}"><td>${esc(S.teams[r.id].name)}</td><td>${r.w}–${r.d}–${r.l}</td><td>${r.mf}:${r.ma}</td><td>${r.bh}</td></tr>`).join('')}</tbody></table></div>`}
bracketView=function(){let available=S.events.filter(e=>e.done||e.id===S.active?.event),e=available.find(e=>e.id===(selectedBracket??S.active?.event))||available.at(-1);if(!e||e.format!=='circuit-v6')return bracketLegacy6();let active=S.active?.event===e.id?S.active:null,a=active||{schedule:e.schedule6,seeds:e.seeds6,entrants:e.entrants,groupIds:e.groupIds6,gsl:e.gsl6},f=format6(e);return head('ТУРНИРНЫЙ ЦЕНТР',e.name,active?active.stage:'Чемпион — '+S.teams[e.champion].name,active?btn('Мой матч →',"go('match')",true):'')+`<div class="filters"><select aria-label="Турнир" onchange="selectedBracket=+this.value;render()">${available.map(v=>`<option value="${v.id}" ${v.id===e.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div><section class="panel"><h2>Регламент</h2><p>${f.label}</p><p class="sub">${f.note} Призовые распределяются по игровым долям. ${e.pairingFallback?'В одном из раундов применён резервный посев с возможным повторным соперником.':''}</p>${f.url?`<a href="${f.url}" target="_blank" rel="noopener">Источник формата ↗</a>`:''}</section>${f.kind==='de'?'':`<section class="panel"><h2>Результаты группового этапа</h2><p class="sub">Порядок: очки (3 за победу, 1 за ничью), Бухгольц, разница карт, выигранные карты, стартовая сила, ID. В GSL выход определяется матчами победителей и решающими матчами, а не этой суммарной таблицей.</p>${a.groupIds?a.groupIds.map((ids,i)=>'<h3>Группа '+String.fromCharCode(65+i)+'</h3>'+circuitTable6(a,ids)).join(''):circuitTable6(a,a.entrants)}</section>`}<div class="cards">${a.schedule.map(n=>{let pair=n.pair.map(v=>resolve6(a,v)),live=active&&n.id===a.cursor;return `<section class="panel ${live?'own-row':''}"><span class="tag dim">${n.label} · BO${n.bo}</span><h3>${pair.map(id=>id==null?'Ожидание результата':esc(S.teams[id].name)).join(' — ')}</h3><strong>${n.score||(live?a.score.join(':'):'—')}</strong>${n.w!=null?'<p class="sub">Победитель: '+esc(S.teams[n.w].short)+'</p>':''}${live?btn('Открыть серию',"go('match')",true):''}</section>`}).join('')}</div>`+restPanel6()};
calendar=function(){return calendarBase6().replace('Для всех турниров используется игровой формат: 16 клубов, 4 группы по 4, затем плей-офф на 8 команд; BO3 и финал BO5. Это не официальные регламенты серий.','У серий разные форматы. Ниже указан шаблон и его источник; для будущих выпусков это сценарий карьеры. Начатый до обновления турнир сохраняет старую сетку.').replaceAll('16 команд<br>','Команды и этапы — по регламенту ниже<br>')+`<section class="panel"><h2>Форматы серий</h2>${S.events.filter(e=>!e.done).map(e=>{let f=format6(e);return `<div class="news"><b>${esc(e.name)}</b><p>${f.label}</p><small>${f.note}</small>${f.url?`<p><a href="${f.url}" target="_blank" rel="noopener">Источник ↗</a></p>`:''}</div>`}).join('')}</section>`};
const validBase6=validSave;validSave=function(x){if(!x||!Array.isArray(x.teams)||x.teams.length!==24)return validBase6(x);let copy={...x,teams:x.teams.slice(0,16),players:x.players.map(p=>({...p,team:p.team>=16?null:p.team})),club:Math.min(x.club,15)};return validBase6(copy)&&x.club<24&&x.teams.every((t,i)=>t.id===i&&[0,1,2,3,4].every(r=>x.players.filter(p=>p.team===i&&p.active&&p.role===r).length===1))};

simulateSeries=function(pair,final=false){let r=aiSeries6(pair,final?5:3);return {pair:[...pair],winner:r.w,score:r.score,maps:r.maps}};
